/// `context.mu` — the MatchUp colours of the current theme.
extension MuThemeX on BuildContext {
  /// The [MuColors] of the nearest Theme (installed by [MuTheme.light] / [MuTheme.dark]).
  MuColors get mu => Theme.of(this).extension<MuColors>()!;
}

/// The three sports. Sport colours only categorise (chips, pins, card accents, courts) and always
/// travel with the sport icon and label; text in a sport hue uses [text], tints use [soft].
enum MuSport {
  football,
  padel,
  basketball;

  /// The French label shown next to the icon.
  String get label => switch (this) {
        MuSport.football => 'Football',
        MuSport.padel => 'Padel',
        MuSport.basketball => 'Basket',
      };

  /// Path of the custom sport icon (see flutter/README.md, « Sport icons »).
  String get asset => switch (this) {
        MuSport.football => 'assets/icons/sport/football.svg',
        MuSport.padel => 'assets/icons/sport/padel.svg',
        MuSport.basketball => 'assets/icons/sport/basketball.svg',
      };

  /// The sport hue for marks: chip icons, map pins, card accents, courts (`football`, `padel`, `basketball`).
  Color color(MuColors c) => switch (this) {
        MuSport.football => c.football,
        MuSport.padel => c.padel,
        MuSport.basketball => c.basketball,
      };

  /// Text and icons in the sport hue on surface, bg and the soft tint (`<sport>-text`).
  Color text(MuColors c) => switch (this) {
        MuSport.football => c.footballText,
        MuSport.padel => c.padelText,
        MuSport.basketball => c.basketballText,
      };

  /// Chip and tile background behind [text] (`<sport>-soft`).
  Color soft(MuColors c) => switch (this) {
        MuSport.football => c.footballSoft,
        MuSport.padel => c.padelSoft,
        MuSport.basketball => c.basketballSoft,
      };
}

/// Colour tones shared by badges, banners, toasts and progress bars. Status is never colour alone:
/// always pair a tone with an icon and a label.
enum MuTone {
  primary,
  success,
  warning,
  error,
  info,
  ai;

  /// Marks, dots, fills and progress bars (`primary`, `success`, `warning`, `error`, `info`, `ai-500`).
  Color color(MuColors c) => switch (this) {
        MuTone.primary => c.primary,
        MuTone.success => c.success,
        MuTone.warning => c.warning,
        MuTone.error => c.error,
        MuTone.info => c.info,
        MuTone.ai => c.ai500,
      };

  /// Text and icons on surface, bg and [soft] (`<tone>-text`; `text` for primary).
  Color text(MuColors c) => switch (this) {
        MuTone.primary => c.text,
        MuTone.success => c.successText,
        MuTone.warning => c.warningText,
        MuTone.error => c.errorText,
        MuTone.info => c.infoText,
        MuTone.ai => c.aiText,
      };

  /// Badge and banner background (`<tone>-soft`; `surface-muted` for primary).
  Color soft(MuColors c) => switch (this) {
        MuTone.primary => c.surfaceMuted,
        MuTone.success => c.successSoft,
        MuTone.warning => c.warningSoft,
        MuTone.error => c.errorSoft,
        MuTone.info => c.infoSoft,
        MuTone.ai => c.aiSoft,
      };
}

/// Chart series slots, in their fixed order (never cycled; past 8 series fold into « Autres »).
enum MuChartColor {
  chart1,
  chart2,
  chart3,
  chart4,
  chart5,
  chart6,
  chart7,
  chart8;

  /// The series colour for the current theme.
  Color color(MuColors c) => switch (this) {
        MuChartColor.chart1 => c.chart1,
        MuChartColor.chart2 => c.chart2,
        MuChartColor.chart3 => c.chart3,
        MuChartColor.chart4 => c.chart4,
        MuChartColor.chart5 => c.chart5,
        MuChartColor.chart6 => c.chart6,
        MuChartColor.chart7 => c.chart7,
        MuChartColor.chart8 => c.chart8,
      };
}
